package io.github.testlens.migration.tooling;
import org.junit.jupiter.api.Test;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
class GitPorcelainV2ParserTest{
 @Test void nulParserPreservesWhitespaceUnicodeTabsNewlinesLeadingDashAndRenameOrigins(){String raw="# branch.oid abc\n# branch.head main\u00001 M. N... 100644 100644 100644 aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb space ü\tline\n-dash\u00002 R. N... 100644 100644 100644 aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb R100 new name\u0000old name\u0000? untracked\nname\u0000";var p=new GitPorcelainV2Parser().parse(raw.getBytes(StandardCharsets.UTF_8));assertEquals("space ü\tline\n-dash",p.staged().get(0).logicalPath());assertEquals("new name",p.renames().get(0).logicalPath());assertEquals("old name",p.renames().get(0).originalLogicalPath());assertEquals("untracked\nname",p.untracked().get(0).logicalPath());}
 @Test void truncatedRenameIsRejected(){assertThrows(GitPorcelainV2Parser.Format.class,()->new GitPorcelainV2Parser().parse(("2 R. N... 100644 100644 100644 "+"a".repeat(40)+" "+"b".repeat(40)+" R100 new\0").getBytes(StandardCharsets.UTF_8)));}
 @Test void indexModeAndObjectComeFromMachineFieldsForBothRoles(){String raw="1 MM N... 100755 100644 100600 "+"a".repeat(40)+" "+"b".repeat(40)+" both.txt\0";var parsed=new GitPorcelainV2Parser().parse(raw.getBytes(StandardCharsets.UTF_8));assertEquals("100644",parsed.staged().get(0).indexMode());assertEquals("b".repeat(40),parsed.staged().get(0).indexObjectId());assertEquals("100644",parsed.unstaged().get(0).indexMode());assertEquals("b".repeat(40),parsed.unstaged().get(0).indexObjectId());}
 @Test void malformedUtf8IsRejectedInsteadOfCollapsingDistinctNames(){assertThrows(GitPorcelainV2Parser.Format.class,()->GitPorcelainV2Parser.nul(new byte[]{'?', ' ',(byte)0xC3,0}));}
}
